151: func (b *Browser) newExecutorForTarget(ctx context.Context, targetID target.ID, sessionID target.SessionID) (*Target, error) {
152: 	if targetID == "" {
153: 		return nil, errors.New("empty target ID")
154: 	}
155: 	if sessionID == "" {
156: 		return nil, errors.New("empty session ID")
157: 	}
158: 	t := &Target{
159: 		browser:   b,
160: 		TargetID:  targetID,
161: 		SessionID: sessionID,
162: 
163: 		messageQueue: make(chan *cdproto.Message, 1024),
164: 		frames:       make(map[cdp.FrameID]*cdp.Frame),
165: 		execContexts: make(map[cdp.FrameID]runtime.ExecutionContextID),
166: 		cur:          cdp.FrameID(targetID),
167: 
168: 		logf: b.logf,
169: 		errf: b.errf,
170: 	}
171: 
172: 	// This send should be blocking, to ensure the tab is inserted into the
173: 	// map before any more target events are routed.
174: 	select {
175: 	case <-ctx.Done():
176: 		return nil, ctx.Err()
177: 	case b.newTabQueue <- t:
178: 	}
179: 	return t, nil
180: }
