182: func (b *Browser) Execute(ctx context.Context, method string, params, res any) error {
183: 	// Certain methods aren't available to the user directly.
184: 	if method == browser.CommandClose {
185: 		return fmt.Errorf("to close the browser gracefully, use chromedp.Cancel")
186: 	}
187: 	return b.execute(ctx, method, params, res)
188: }
