190: func (b *Browser) execute(ctx context.Context, method string, params, res any) error {
191: 	id := atomic.AddInt64(&b.next, 1)
192: 	lctx, cancel := context.WithCancel(ctx)
193: 	ch := make(chan *cdproto.Message, 1)
194: 	fn := func(ev any) {
195: 		if msg, ok := ev.(*cdproto.Message); ok && msg.ID == id {
196: 			select {
197: 			case <-ctx.Done():
198: 			case ch <- msg:
199: 			}
200: 			cancel()
201: 		}
202: 	}
203: 	b.listenersMu.Lock()
204: 	b.listeners = append(b.listeners, cancelableListener{lctx, fn})
