1: package chromedp
2: 
3: import (
4: 	"bytes"
5: 	"context"
6: 	"io"
7: 	"net"
8: 
9: 	"github.com/chromedp/cdproto"
10: 	jsonv2 "github.com/go-json-experiment/json"
11: 	"github.com/go-json-experiment/json/jsontext"
12: 	"github.com/gobwas/ws"
13: 	"github.com/gobwas/ws/wsutil"
14: )
15: 
16: // Transport is the common interface to send/receive messages to a target.
17: //
18: // This interface is currently used internally by Browser, but it is exposed as
19: // it will be useful as part of the public API in the future.
20: type Transport interface {
21: 	Read(context.Context, *cdproto.Message) error
22: 	Write(context.Context, *cdproto.Message) error
23: 	io.Closer
24: }
25: 
26: // Conn implements Transport with a gobwas/ws websocket connection.
27: type Conn struct {
28: 	conn net.Conn
29: 
30: 	// reuse the websocket reader and writer to avoid an alloc per
31: 	// Read/Write.
32: 	reader wsutil.Reader
33: 	writer wsutil.Writer
34: 
35: 	// reuse the easyjson structs to avoid allocs per Read/Write.
36: 	decoder jsontext.Decoder
37: 	encoder jsontext.Encoder
38: 
39: 	debugf func(string, ...any)
40: }
41: 
42: // DialContext dials the specified websocket URL using gobwas/ws.
43: func DialContext(ctx context.Context, urlstr string, opts ...DialOption) (*Conn, error) {
44: 	// connect
45: 	conn, br, _, err := ws.Dial(ctx, urlstr)
46: 	if err != nil {
47: 		return nil, err
48: 	}
49: 	if br != nil {
50: 		panic("br should be nil")
51: 	}
52: 
53: 	// apply opts
54: 	c := &Conn{
55: 		conn: conn,
56: 		// pass 0 to use the default initial buffer size (4KiB).
57: 		// github.com/gobwas/ws will grow the buffer size if needed.
58: 		writer: *wsutil.NewWriterBufferSize(conn, ws.StateClientSide, ws.OpText, 0),
59: 	}
60: 	for _, o := range opts {
61: 		o(c)
62: 	}
63: 
64: 	return c, nil
65: }
66: 
67: // Close satisfies the io.Closer interface.
68: func (c *Conn) Close() error {
69: 	return c.conn.Close()
70: }
71: 
72: // Read reads the next message.
73: func (c *Conn) Read(_ context.Context, msg *cdproto.Message) error {
74: 	// get websocket reader
75: 	c.reader = wsutil.Reader{Source: c.conn, State: ws.StateClientSide}
76: 	h, err := c.reader.NextFrame()
77: 	if err != nil {
78: 		return err
79: 	}
80: 
81: 	if h.OpCode == ws.OpPing { // ping
82: 		if c.debugf != nil {
83: 			c.debugf("received ping frame, ignoring...")
84: 		}
85: 		return nil
86: 	} else if h.OpCode == ws.OpClose { // close
87: 		if c.debugf != nil {
88: 			c.debugf("received close frame")
89: 		}
90: 		return io.EOF
91: 	} else if h.OpCode != ws.OpText {
92: 		if c.debugf != nil {
93: 			c.debugf("unknown OpCode: %s", h.OpCode)
94: 		}
95: 		return ErrInvalidWebsocketMessage
96: 	}
97: 
98: 	var b bytes.Buffer
99: 	if _, err := b.ReadFrom(&c.reader); err != nil {
100: 		return err
101: 	}
102: 
103: 	if c.debugf != nil {
104: 		c.debugf("<- %s", b.Bytes())
105: 	}
106: 
107: 	// unmarshal, reusing decoder
108: 	c.decoder.Reset(&b, DefaultUnmarshalOptions)
109: 	return jsonv2.UnmarshalDecode(&c.decoder, msg, DefaultUnmarshalOptions)
110: }
111: 
112: // Write writes a message.
113: func (c *Conn) Write(_ context.Context, msg *cdproto.Message) error {
114: 	c.writer.Reset(c.conn, ws.StateClientSide, ws.OpText)
115: 	// Chrome doesn't support fragmentation of incoming websocket messages. To
116: 	// compensate this, they support single-fragment messages of up to 100MiB.
117: 	//
